rd=(f,mx=640)=>new Promise(ok=>{const r=new FileReader();r.onerror=()=>ok(null);r.onload=()=>{const im=new Image();im.onerror=()=>ok(null);im.onload=()=>{const k=Math.min(1,mx/Math.max(im.width,im.height)),c=document.createElement('canvas'),x=c.getContext('2d');c.width=im.width*k;c.height=im.height*k;x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);ok(c.toDataURL('image/jpeg',.72))};im.src=r.result};r.readAsDataURL(f)}),
