dlf=async id=>{const p=S.p.find(x=>x.id==id);if(!p)return;await call(async()=>{const u=await okq(SB.rpc('get_download_url',{p_product_id:id}));if(!u)throw new Error('The seller hasn’t attached the file yet — please contact support');let url=u;if(!/^https?:\/\//.test(u)){const{data,error}=await SB.storage.from('downloads').createSignedUrl(u,300,{download:p.fname||true});if(error)throw error;url=data.signedUrl}const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';document.body.appendChild(a);a.click();a.remove()})},
