oc=o=>{if(o.cx)return occ(o);const dg=isDig(o);return `<div class=box><div class=ah><b>${e(o.id)}</b><span class=mu>${new Date(o.at).toLocaleString('en-IN')}</span></div><h4>👤 ${e(o.name)}</h4><p>📞 <a class=lk href="tel:${e(o.phone)}">${e(o.phone)}</a> · <a class=lk href="https://wa.me/91${e(o.phone)}?text=${encodeURIComponent('Hi '+o.name+', this is buyfirst about order '+o.id+(o.paid?' — your payment is approved ✅'+(isDig(o)?'. Open the buyfirst site → My downloads to download your e-book.':'. We are preparing your order.'):'.'))}" target=_blank rel=noopener>💬 Message customer</a>${o.email?' · ✉️ '+e(o.email):''}</p><p class=mu>📍 ${e(o.addr)}</p><p>🛒 ${o.items.map(i=>e(i.t)+(i.v?' ('+e(i.v)+')':'')+' ×'+i.q+' — '+inr(i.price*i.q)).join('<br>')}</p><p>💳 ${e(o.pay)} · <b>${inr(o.total)}</b>${o.utr?' · UTR <b>'+e(o.utr)+'</b>':''}</p>${isDig(o)&&!o.paid&&miss(o).length?'<p style=color:#d93025>⚠️ No file attached to '+miss(o).map(p=>e(p.title)).join(', ')+' — upload it first (E-books → ✏️), then approve.</p>':''}${o.utr?o.paid?'<p class=off>✅ Payment approved'+(dg?' — download unlocked for the customer':'')+'</p>':o.rej?'<p style=color:#d93025>❌ Payment rejected</p>':`<div class=row><button class=btn onclick="payok('${o.id}')">✔ Approve payment${dg?' &amp; unlock download':''}</button><button class="btn g" onclick="payno('${o.id}')">✖ Reject</button></div>`:''}${dg?'':`<label class=mu>Shipping status (customers can cancel only until Shipped)<select class=ss onchange="setSt('${o.id}',this.value)">${ST.map(x=>`<option ${x==o.status?'selected':''}>${x}</option>`).join('')}</select></label>`}<div class=row>${dbtn([o.id,1])}</div></div>`},
