odm=m=>{const o=S.o.find(x=>x.id==m.id);if(!o)return'';const rs=!o.cx&&!isDig(o)&&o.status!='Delivered';return `<h3>Delete order ${e(o.id)}?</h3><p class=mu>${m.adm?'This permanently removes the order from your dashboard'+(rs?' and returns the items to stock':'')+'. '+(o.utr&&!o.paid&&!o.rej?'<b>Its payment has not been approved or rejected yet.</b> ':'')+'This can’t be undone.':'This removes the order from your order history on this device. The seller keeps a record of it.'}</p><button class=btn style="background:#d93025;box-shadow:none" onclick="odo('${o.id}',${m.adm?1:0})">Yes, delete</button><button class="btn g" onclick="S.m=null;ov()">Keep it</button>`},
odo=async(id,adm)=>{const o=S.o.find(x=>x.id==id);if(!o){S.m=null;ov();return}if(!adm&&(!S.me||o.uid!=S.me.id||!cdel(o))){S.m=null;ov();return tt('This order can’t be deleted',1)}if(adm&&!S.adm)return;await call(async()=>{await okq(SB.rpc(adm?'admin_delete_order':'hide_order',{p_id:id}));if(adm){await loadProducts();await loadAdmin()}else await loadMine();S.m=null;draw()},adm?'Order deleted':'Removed from your orders')},
