oco=o=>{const k=ST.indexOf(o.status),dg=isDig(o),pst=o.utr?(o.paid?'✅ Paid':o.rej?'❌ Payment rejected':'⏳ Payment verifying'):'';
return `<div class=box><div class=ah><b>${e(o.id)}</b><span class=mu>${new Date(o.at).toLocaleDateString('en-IN')}</span></div><p>${o.cx?'<b style=color:#d93025>❌ Cancelled</b>':'<b>'+(dg?(o.paid?'✅ Approved — ready to download':'⏳ Awaiting seller approval'):TL[k]||o.status)+'</b>'} ${pst&&!o.cx?' · '+pst:''}</p>${o.items.map(i=>{const p=S.p.find(x=>x.id==i.id);return `<div class=li>${p?pic(p):''}<div><b>${e(i.t)}</b><br><small class=mu>${i.v?e(i.v)+' · ':''}Qty ${i.q}</small><div>${inr(i.price*i.q)}</div></div></div>`}).join('')}<p class=mu>📍 ${e(o.addr)}</p><p>Total <b>${inr(o.total)}</b> · ${e(o.pay)}</p>${o.cx?`<p class=mu>Cancelled on ${new Date(o.cx.at).toLocaleDateString('en-IN')} · ${e(o.cx.why)}</p><a class="btn g" target=_blank rel=noopener href="${wac(o)}">📲 Tell the seller on WhatsApp</a><div class=row style="margin-top:8px">${dbtn([o.id,0])}</div>`:`${dg?'':`<div class=tl>${TL.map((x,i)=>`<div class="${i<=k?'on':''}"><i>${i<=k?'✓':i+1}</i>${x}</div>`).join('')}</div>`}${dls(o)}<div class=row>${canC(o)?`<button class="btn g" style=color:#d93025 onclick="S.m={t:'cx',id:'${o.id}'};ov()">✖ Cancel order</button>`:''}${dg?'':`<button class="btn g" onclick="trkmine('${o.id}')">Track</button>`}${cdel(o)?dbtn([o.id,0]):''}</div>${canC(o)?'':'<p class=mu>'+(k>=2?'Cancellation isn’t available once the order has shipped.':'Approved e-books can’t be cancelled.')+'</p>'}`}</div>`},
ords=()=>{if(!S.me){S.m={t:'auth',mode:'login',note:'Login to see your orders.'};S.pend=()=>go('orders');return'<p class=mu style="margin:20px 0">Please login to see your orders.</p>'}const L=cmine(),f=S.cof||'all';return `<h2>📦 ORDERS</h2>${L.length?`<nav>${CF.map(([k,l])=>`<a class="${f==k?'on':''}" onclick="S.cof='${k}';main()">${l} (${L.filter(o=>cfl(o,k)).length})</a>`).join('')}</nav>${octl(S.cq,S.cos,'S.cq','S.cos')}<div id=ol>${olC()}</div>`:'<p class=mu>You haven’t placed any orders yet. <a class=lk onclick="go(\'home\')">Start shopping</a></p>'}`},
