mkimg=async f=>{const url=await readURL(f);if(!url)return null;const im=await loadImg(url);if(!im)return null;const big=f.size>2.5*1048576||Math.max(im.width,im.height)>3000;if(!big)return{orig:f,disp:f,prev:url,big:0};const k=Math.min(1,2600/Math.max(im.width,im.height)),c=document.createElement('canvas'),x=c.getContext('2d');c.width=im.width*k;c.height=im.height*k;x.fillStyle='#fff';x.fillRect(0,0,c.width,c.height);x.drawImage(im,0,0,c.width,c.height);const d=await new Promise(ok=>c.toBlob(ok,'image/jpeg',.95));if(!d)return{orig:f,disp:f,prev:url,big:0};return{orig:f,disp:d,prev:await readURL(d),big:1}},
